PROGRAM Main
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    MotorFeedback : BOOL;
    OverloadOK : BOOL;
END_VAR
VAR_OUTPUT
    MotorContactor : BOOL;
    RunLamp : BOOL;
END_VAR
MotorContactor := (StartPB OR MotorContactor) AND StopPB AND OverloadOK;
RunLamp := MotorFeedback;
END_PROGRAM
